import subprocess
import sys

def _ensure_deps():
    try:
        import telegram as _telegram
        from telegram import Update as _Update
        from telegram.ext import Application as _Application
        version = str(getattr(_telegram, "__version__", ""))
        if version != "20.7":
            print(f"[YUTA SETUP] python-telegram-bot {version or 'unknown'} found; installing 20.7...")
            subprocess.check_call([sys.executable, "-m", "pip", "install", "--force-reinstall", "python-telegram-bot==20.7"])
            import telegram as _telegram2
            from telegram import Update as _Update2
            from telegram.ext import Application as _Application2
        print(f"[YUTA SETUP] python-telegram-bot {getattr(_telegram, '__version__', '20.7')} ready.", flush=True)
    except Exception as exc:
        raise ImportError(
            "python-telegram-bot==20.7 is required. Install with: "
            "python -m pip install --force-reinstall python-telegram-bot==20.7. "
            f"Import error: {exc}"
        ) from exc

