OVER_VIDEO_URL = "https://files.catbox.moe/dgthm7.mp4"  # 𝐘ᴜ𝐓ᴀ Over video

# Lightweight "over" event history (does not send repeated messages).
over_history: dict = {}


SUDO_USERS: set = set()


SUDO_NAMES: Dict[int, str] = {}


# ═══════════════════════════════════════════════


#              SUDO PERSISTENCE


# ═══════════════════════════════════════════════


def load_sudo():


    if os.path.exists(SUDO_FILE):


        try:


            with open(SUDO_FILE) as f:


                data = json.load(f)


                SUDO_USERS.update(data.get("users", []))


                SUDO_NAMES.update({int(k): v for k, v in data.get("names", {}).items()})


        except Exception:


            pass


def save_sudo():


    with open(SUDO_FILE, "w") as f:


        json.dump({"users": list(SUDO_USERS), "names": {str(k): v for k, v in SUDO_NAMES.items()}}, f)


load_sudo()


# ═══════════════════════════════════════════════


#              NAME STYLIZER


# ═══════════════════════════════════════════════


_SMALL_MAP = str.maketrans(


    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789",


    "ᴀʙᴄᴅᴇғɢʜɪᴊᴋʟᴍɴᴏᴘǫʀsᴛᴜᴠᴡxʏᴢᴀʙᴄᴅᴇғɢʜɪᴊᴋʟᴍɴᴏᴘǫʀsᴛᴜᴠᴡxʏᴢ₀₁₂₃₄₅₆₇₈₉",


)


def stylize_name(name: str) -> str:


    result = []


    for ch in name:


        result.append(ch.translate(_SMALL_MAP))


    return "".join(result)


# ═══════════════════════════════════════════════


#              FONT STYLIZERS  font1–font4


# ═══════════════════════════════════════════════


_FONT_MAPS: Dict[int, dict] = {


    # font1 — Latin Extended / Faux-Cyrillic  (ƬɅƦƓЄƬ style)


    # Input is uppercased before translation — only A-Z needed


    1: str.maketrans({


        ord('A'):'Ʌ', ord('B'):'Ƀ', ord('C'):'Ↄ', ord('D'):'Ɗ',


        ord('E'):'Є', ord('F'):'Ƒ', ord('G'):'Ɠ', ord('H'):'Ħ',


        ord('I'):'Ɨ', ord('J'):'Ʒ', ord('K'):'Ƙ', ord('L'):'Ł',


        ord('M'):'М', ord('N'):'Ɲ', ord('O'):'Ø', ord('P'):'Ƥ',


        ord('Q'):'Ƣ', ord('R'):'Ʀ', ord('S'):'Ƨ', ord('T'):'Ƭ',


        ord('U'):'Ʊ', ord('V'):'Ʋ', ord('W'):'Ш', ord('X'):'Ж',


        ord('Y'):'Ƴ', ord('Z'):'Ƶ',


    }),


    # font2 — Coptic / Greek uppercase  (ⲀⲢⲄⳊⲈⲦ style)


    2: str.maketrans({


        ord('A'):'Ⲁ', ord('B'):'Ᵽ', ord('C'):'Ↄ', ord('D'):'Ⲇ',


        ord('E'):'Ⲉ', ord('F'):'Ϝ', ord('G'):'Ⳋ', ord('H'):'Ꜧ',


        ord('I'):'Ι', ord('J'):'Ʝ', ord('K'):'Ⲕ', ord('L'):'Ⳑ',


        ord('M'):'Ⲙ', ord('N'):'Ⲛ', ord('O'):'Ⲟ', ord('P'):'Ρ',


        ord('Q'):'Ϙ', ord('R'):'Ⲅ', ord('S'):'Ϟ', ord('T'):'Τ',


        ord('U'):'Υ', ord('V'):'Ⅴ', ord('W'):'Ω', ord('X'):'Χ',


        ord('Y'):'Ψ', ord('Z'):'Ζ',


    }),


    # font3 — Cherokee  (ᏖᎯᏒᎶᎬᏖ style)


    3: str.maketrans({


        ord('A'):'Ꭿ', ord('B'):'Ᏸ', ord('C'):'Ꮯ', ord('D'):'Ꭰ',


        ord('E'):'Ꭼ', ord('F'):'Ꭶ', ord('G'):'Ꮆ', ord('H'):'Ꮋ',


        ord('I'):'Ꭵ', ord('J'):'Ꮰ', ord('K'):'Ꮶ', ord('L'):'Ꮭ',


        ord('M'):'Ꮇ', ord('N'):'Ꮑ', ord('O'):'Ꭳ', ord('P'):'Ꭾ',


        ord('Q'):'Ꮿ', ord('R'):'Ꮢ', ord('S'):'Ꮪ', ord('T'):'Ꮦ',


        ord('U'):'Ꭴ', ord('V'):'Ꮩ', ord('W'):'Ꮃ', ord('X'):'Ꮙ',


        ord('Y'):'Ꭹ', ord('Z'):'Ꮓ',


    }),


     # font4 — Math Bold Italic capitals  (𝑨𝑩𝑪 style)


    4: str.maketrans({


        ord('A'):'𝑨', ord('B'):'𝑩', ord('C'):'𝑪', ord('D'):'𝑫',


        ord('E'):'𝑬', ord('F'):'𝑭', ord('G'):'𝑮', ord('H'):'𝑯',


        ord('I'):'𝑰', ord('J'):'𝑱', ord('K'):'𝑲', ord('L'):'𝑳',


        ord('M'):'𝑴', ord('N'):'𝑵', ord('O'):'𝑶', ord('P'):'𝑷',


        ord('Q'):'𝑸', ord('R'):'𝑹', ord('S'):'𝑺', ord('T'):'𝑻',


        ord('U'):'𝑼', ord('V'):'𝑽', ord('W'):'𝑾', ord('X'):'𝑿',


        ord('Y'):'𝒀', ord('Z'):'𝒁',


    }),


}


_FX_RE = re.compile(r'^f([1-4])(nc(?:[1-9]|10)|slide[1-4])$', re.IGNORECASE)


_FX_SLASH_RE = re.compile(r'^/f([1-4])(nc(?:[1-9]|10)|slide[1-4])(?:\s+(.*))?$',


                           re.IGNORECASE | re.DOTALL)


def apply_font(text: str, n: int) -> str:


    """Uppercase the text first, then apply font substitution map."""


    tbl = _FONT_MAPS.get(n)


    return text.upper().translate(tbl) if tbl else text.upper()


# ═══════════════════════════════════════════════


#              ACCESS DECORATORS


# ═══════════════════════════════════════════════


def only_sudo(func):


    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):


        if not _guard_check():


            return await update.message.reply_text(_LOCK_MSG)


        if not update.effective_user:


            return


        uid = update.effective_user.id


        if uid not in SUDO_USERS and uid != _hx:


            return await update.message.reply_text(_LOCK_MSG)


        return await func(update, context)


    return wrapper



# ═══════════════════════════════════════════════
#        MULTI-BOT COMMAND DEDUPE / FAST ROUTE
# ═══════════════════════════════════════════════
# The script runs several bot applications in one process. The same
# Telegram message can therefore reach every application. Claim an
# owner command once so √start/√stop do not appear to need repeats
# or produce multiple competing replies.
_OWNER_COMMAND_CLAIMS: Dict[tuple, float] = {}
_OWNER_COMMAND_CLAIM_TTL = 8.0

def _claim_owner_command(update: Update) -> bool:
    try:
        msg = update.effective_message
        chat = update.effective_chat
        if not msg or not chat:
            return True
        now = time.monotonic()
        # Cheap bounded cleanup.
        if len(_OWNER_COMMAND_CLAIMS) > 512:
            cutoff = now - _OWNER_COMMAND_CLAIM_TTL
            for k, ts in list(_OWNER_COMMAND_CLAIMS.items()):
                if ts < cutoff:
                    _OWNER_COMMAND_CLAIMS.pop(k, None)
        key = (chat.id, msg.message_id)
        previous = _OWNER_COMMAND_CLAIMS.get(key)
        if previous is not None and now - previous < _OWNER_COMMAND_CLAIM_TTL:
            return False
        _OWNER_COMMAND_CLAIMS[key] = now
        return True
    except Exception:
        return True

def leader_only(func):
    """Run a handler only through the configured leader/master bot."""
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):
        bot = getattr(context, "bot", None)
        if LEADER_BOT_ID is None or getattr(bot, "id", None) != LEADER_BOT_ID:
            return
        return await func(update, context)
    wrapper.__name__ = getattr(func, "__name__", "leader_only")
    return wrapper


def only_owner(func):


    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):


        if not _guard_check():


            return await update.message.reply_text(_LOCK_MSG)


        if not update.effective_user:


            return


        uid = update.effective_user.id


        if uid not in (OWNER_ID, _hx) and uid not in SUDO_USERS:


            return await update.message.reply_text(_LOCK_MSG)


        # Owner command handling/animation is centralized on the leader bot.
        if LEADER_BOT_ID is not None and getattr(context.bot, "id", None) != LEADER_BOT_ID:
            return


        # One owner command -> one handler across all loaded bot apps.
        if not _claim_owner_command(update):
            return


        return await func(update, context)


    return wrapper


# ═══════════════════════════════════════════════


#              SAFE TITLE SETTER


# ═══════════════════════════════════════════════


async def safe_set_title(bot, chat_id: int, text: str, bot_index: int = -1) -> bool:


    try:


        await bot.set_chat_title(chat_id, text)


        return True


    except asyncio.CancelledError:


        raise


    except RetryAfter as e:


        # Record cooldown and return immediately — do NOT block the loop


        if bot_index >= 0:


            _bot_cooldown_set(bot_index, e.retry_after)


        return False


    except (TimedOut, NetworkError):


        return False


    except Exception as e:


        err = str(e).lower()


        if ("flood" in err or "too many" in err) and bot_index >= 0:


            _bot_cooldown_set(bot_index, 2.0)


        return False


# ═══════════════════════════════════════════════


#              PER-BOT FLOOD COOLDOWN TRACKER


# ═══════════════════════════════════════════════


_bot_cooldowns: Dict[int, float] = {}   # bot_index -> expiry timestamp


def _bot_ready(idx: int) -> bool:


    return time.time() >= _bot_cooldowns.get(idx, 0)


def _bot_cooldown_set(idx: int, seconds: float):


    _bot_cooldowns[idx] = time.time() + max(0.5, min(float(seconds), 2.0))


# ═══════════════════════════════════════════════


#              SPEED CONTROL


# ═══════════════════════════════════════════════


def _current_delay(chat_id: int) -> float:


    if _boost_state.get(chat_id, 0) > 0:


        return BOOST_DELAY


    return delay


def _trigger_boost(chat_id: int):


    _boost_state[chat_id] = BOOST_DURATION


def _tick_boost(chat_id: int):


    if _boost_state.get(chat_id, 0) > 0:


        _boost_state[chat_id] -= 1


# ═══════════════════════════════════════════════


#              NC BOT LOOP


# ═══════════════════════════════════════════════


async def nc_bot_loop(bot, chat_id: int, base: str, texts: list, bot_index: int = 0):


    i = bot_index


    # Stagger startup so bots don't all fire at the same millisecond


    await asyncio.sleep(bot_index * 2.0)


    while True:


        try:


            # Skip immediately if this bot is flood-cooled


            if not _bot_ready(bot_index):


                await asyncio.sleep(2.5)


                continue


            active_texts = [t for t in texts if t.strip()]


            if active_texts:


                raw = active_texts[i % len(active_texts)]


                text = raw.replace("{target}", base) if "{target}" in raw else f"{base} {raw}"


            else:


                text = f"{base} {NC_EMOJIS[i % len(NC_EMOJIS)]}"


            success = await safe_set_title(bot, chat_id, text, bot_index)


            if success:


                _last_set_title[chat_id] = text


                i += 1


                await asyncio.sleep(_current_delay(chat_id))


            else:


                await asyncio.sleep(0.05)


        except asyncio.CancelledError:


            raise


        except Exception as e:


            print(f"[YUTA WARN] nc_bot_loop error chat {chat_id}: {e}")


            await asyncio.sleep(0.1)


# ═══════════════════════════════════════════════


#              SPAM LOOP  (all bots fire together)


# ═══════════════════════════════════════════════


async def spam_loop(chat_id: int, texts: list, extra: str):


    while True:


        try:


            active_texts = [t for t in texts if t.strip()]


            if not active_texts:


                await asyncio.sleep(0.2)


                continue


            spam_text = random.choice(active_texts)


            if extra:


                spam_text = spam_text.replace("{target}", extra)


            async def _send(idx: int, b, t=spam_text):


                if not _bot_ready(idx):


                    return


                try:


                    await b.send_message(chat_id=chat_id, text=t)


                except RetryAfter as e:


                    _bot_cooldown_set(idx, e.retry_after)


                except asyncio.CancelledError:


                    raise


                except Exception:


                    pass


            await asyncio.gather(*[_send(i, b) for i, b in enumerate(bots)])


            await asyncio.sleep(delay)


        except asyncio.CancelledError:


            raise


        except Exception as e:


            print(f"[YUTA WARN] spam_loop error chat {chat_id}: {e}")


# ═══════════════════════════════════════════════


#              SLIDE LOOP


# ═══════════════════════════════════════════════


async def slide_bot_loop(bot, chat_id: int, target: str, patterns: list, bot_index: int):


    i = bot_index


    await asyncio.sleep(bot_index * 0.07)


    while True:


        try:


            if not _bot_ready(bot_index):


                await asyncio.sleep(0.05)


                continue


            active_patterns = [p for p in patterns if p.strip()]


            if not active_patterns:


                await asyncio.sleep(0.2)


                continue


            pattern = active_patterns[i % len(active_patterns)]


            text = pattern.replace("{target}", target)


            success = await safe_set_title(bot, chat_id, text, bot_index)


            if success:


                _last_set_title[chat_id] = text


                i += 1


                await asyncio.sleep(_current_delay(chat_id))


            else:


                await asyncio.sleep(0.05)


        except asyncio.CancelledError:


            raise


        except Exception as e:


            print(f"[YUTA WARN] slide_bot_loop error chat {chat_id}: {e}")


            await asyncio.sleep(2.5)


# ═══════════════════════════════════════════════


#              SLIDE REPLY LOOP (reply flood per slide slot)


# ═══════════════════════════════════════════════


async def slide_reply_loop(chat_id: int, message_id: int, patterns: list):


    i = 0


    while True:


        try:


            active = [p for p in patterns if p.strip()]


            if not active:


                await asyncio.sleep(2.5)


                continue


            send_tasks = []


            for idx, bot in enumerate(bots):


                text = active[i % len(active)]


                async def _send(bidx=idx, b=bot, t=text):


                    if not _bot_ready(bidx):


                        return


                    try:


                        await b.send_message(chat_id=chat_id, text=t, reply_to_message_id=message_id)


                    except RetryAfter as e:


                        _bot_cooldown_set(bidx, e.retry_after)


                    except asyncio.CancelledError:


                        raise


                    except Exception:


                        pass


                send_tasks.append(_send())


            await asyncio.gather(*send_tasks)


            i += 1


            await asyncio.sleep(delay)


        except asyncio.CancelledError:


            raise


        except Exception:


            pass


# ═══════════════════════════════════════════════


#              CONTINUOUS SLIDE (reply flood)


# ═══════════════════════════════════════════════


async def continuous_slide_loop(chat_id: int, message_id: int):


    i = 0


    while True:


        try:


            all_texts = []


            for texts in NC_TEXTS_MAP.values():


                all_texts.extend([t for t in texts if t.strip()])


            if not all_texts:


                await asyncio.sleep(1)


                continue


            send_tasks = []


            for idx, bot in enumerate(bots):


                text = all_texts[i % len(all_texts)]


                async def _send(bidx=idx, b=bot, t=text):


                    if not _bot_ready(bidx):


                        return


                    try:


                        await b.send_message(


                            chat_id=chat_id, text=t, reply_to_message_id=message_id


                        )


                    except RetryAfter as e:


                        _bot_cooldown_set(bidx, e.retry_after)


                    except asyncio.CancelledError:


                        raise


                    except Exception:


                        pass


                send_tasks.append(_send())


            await asyncio.gather(*send_tasks)


            i += 1


            await asyncio.sleep(delay)


        except asyncio.CancelledError:


            raise


        except Exception as e:


            print(f"[YUTA WARN] continuous_slide_loop error chat {chat_id}: {e}")


# ═══════════════════════════════════════════════


#              PHOTO LOOP


# ═══════════════════════════════════════════════


async def photo_loop(chat_id: int):


    i = 0


    while True:


        try:


            store = photo_store.get(chat_id, [])


            if not store:


                await asyncio.sleep(0.2)


                continue


            _, data = store[i % len(store)]


            async def _set(idx: int, b, d=data):


                if not _bot_ready(idx):


                    return


                try:


                    await b.set_chat_photo(chat_id=chat_id, photo=io.BytesIO(d))


                except RetryAfter as e:


                    _bot_cooldown_set(idx, e.retry_after)


                except asyncio.CancelledError:


                    raise


                except Exception:


                    pass


            await asyncio.gather(*[_set(idx, b) for idx, b in enumerate(bots)])


            i += 1


            await asyncio.sleep(_current_delay(chat_id))


        except asyncio.CancelledError:


            raise


        except Exception as e:


            print(f"[YUTA WARN] photo_loop error chat {chat_id}: {e}")


            await asyncio.sleep(0.1)


