def _pfp_photo():
    """Return the bundled 𝐘ᴜ𝐓ᴀ PFP as a fresh file-like object."""
    data = base64.b64decode(PFP_IMAGE_B64)
    bio = io.BytesIO(data)
    bio.name = "yuta_keng_pfp.jpg"
    return bio


def _pfp_source():
    """Return the most reliable PFP source: bundled image first, URL as fallback."""
    # The bundled image does not depend on ImgLink/CDN availability, so it prevents
    # the occasional missing-photo issue. The configured URL is still retained for
    # external/manual use and as a secondary fallback.
    if PFP_IMAGE_B64:
        return _pfp_photo()
    return PFP_MEDIA_URL or MENU_PFP_URL or None


def _pfp_sources():
    """Yield reliable PFP sources without exposing failures to the user."""
    if PFP_IMAGE_B64:
        yield _pfp_photo()
    if PFP_MEDIA_URL and not PFP_MEDIA_URL.startswith("embedded://"):
        yield PFP_MEDIA_URL
    elif MENU_PFP_URL and not MENU_PFP_URL.startswith("embedded://"):
        yield MENU_PFP_URL


async def _send_pfp_box(update: Update, text: str, reply_markup=None):
    """Send a polished PFP-backed box with a reliable local-image fallback."""
    if not update.message:
        return
    if len(text) <= 1024:
        for source in _pfp_sources():
            try:
                await update.message.reply_photo(photo=source, caption=text, reply_markup=reply_markup)
                return
            except Exception:
                continue
    else:
        for source in _pfp_sources():
            try:
                await update.message.reply_photo(
                    photo=source,
                    caption="🫧 𝐘ᴜ𝐓ᴀ • 𝐒ᴇꜱꜱʏ",
                )
                await update.message.reply_text(text, reply_markup=reply_markup)
                return
            except Exception:
                continue
    await update.message.reply_text(text, reply_markup=reply_markup)


