def _menu_markup():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🏠 𝗛ᴏᴍᴇ", callback_data="menu_home"), InlineKeyboardButton("👑 𝗢ᴡɴᴇʀ", callback_data="menu_owner")],
        [InlineKeyboardButton("🌺 𝗡𝗖", callback_data="menu_nc"), InlineKeyboardButton("🥷 𝗦ʟɪᴅᴇ", callback_data="menu_slide")],
        [InlineKeyboardButton("🌪️ 𝗦ᴘᴀᴍ", callback_data="menu_spam"), InlineKeyboardButton("👑 𝗖ᴍɴᴅs", callback_data="menu_cmnds")],
        [InlineKeyboardButton("⚡ 𝗥ᴇᴀᴄᴛ", callback_data="menu_react"), InlineKeyboardButton("🪦 𝗢ᴠᴇʀ", callback_data="menu_over")],
        [InlineKeyboardButton("🖼️ 𝐏ғᴘ", callback_data="menu_pfp"), InlineKeyboardButton("🫧 𝗔ʙᴏᴜᴛ", callback_data="menu_about")],
        [InlineKeyboardButton("🫠 𝗦ᴛᴜғғ", callback_data="menu_stuff"), InlineKeyboardButton("👑 𝗠ᴀɴᴀɢᴇ", callback_data="menu_management")],
        [InlineKeyboardButton("📊 𝗦ᴛᴀᴛᴜs", callback_data="menu_home"), InlineKeyboardButton("✖️ 𝗖ʟᴏsᴇ", callback_data="menu_close")],
    ])

async def sessy_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    await query.answer()
    user = query.from_user
    if LEADER_BOT_ID is not None and getattr(context.bot, "id", None) != LEADER_BOT_ID:
        return
    if not user or not _is_owner_uid(user.id) or not _guard_check():
        return
    data = query.data or ""
    if data == "menu_close":
        await query.edit_message_text("📂 𝗠ᴇɴᴜ 𝗧ᴀʙ 𝗖ʟᴏsᴇᴅ.")
        return
    if data.startswith("menu_"):
        tab = data[5:]
        text = _menu_tab_text(tab)
        # Photo messages can carry the Catbox PFP; text messages remain the fallback.
        try:
            if PFP_MEDIA_URL and query.message and query.message.photo:
                await query.edit_message_caption(caption=text, reply_markup=_menu_markup())
            elif query.message:
                sent = False
                for source in _pfp_sources():
                    try:
                        await query.message.delete()
                        await context.bot.send_photo(chat_id=query.message.chat_id, photo=source, caption=text, reply_markup=_menu_markup())
                        sent = True
                        break
                    except Exception:
                        continue
                if sent:
                    return
            else:
                await query.edit_message_text(text, reply_markup=_menu_markup())
        except Exception:
            try:
                await query.edit_message_text(text, reply_markup=_menu_markup())
            except Exception:
                pass
        return
    if data == "sessy_close":
        await query.edit_message_text("📂 𝗦ᴇꜱꜱʏ 𝗧ᴀʙ 𝗖ʟᴏꜱᴇᴅ.")
        return
    await query.edit_message_text(_sessy_text(), reply_markup=InlineKeyboardMarkup([[
        InlineKeyboardButton("🔄 𝗥ᴇғʀᴇsʜ", callback_data="sessy_refresh"),
        InlineKeyboardButton("✖️ 𝗖ʟᴏsᴇ", callback_data="sessy_close"),
    ]]))

@leader_only
@only_owner
async def ping_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    frames = [
        "╭━━━━━━━━〔 ⚡ 𝗦ʏsᴛᴇᴍ 𝗖ᴏʀᴇ 〕━━━━━━━━╮\n│ ◉ 𝗖ᴏʀᴇ 𝗕ᴏᴏᴛɪɴɢ...\n│ ▰▱▱▱▱▱▱▱▱▱  10%\n╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━╯",
        "╭━━━━━━━━〔 ⚡ 𝗦ʏsᴛᴇᴍ 𝗖ᴏʀᴇ 〕━━━━━━━━╮\n│ ◉ 𝗣ᴏᴡᴇʀ 𝗖ʜᴇᴄᴋ...\n│ ▰▰▰▰▱▱▱▱▱▱  45%\n╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━╯",
        "╭━━━━━━━━〔 ⚡ 𝗦ʏsᴛᴇᴍ 𝗖ᴏʀᴇ 〕━━━━━━━━╮\n│ ◉ 𝗡ᴇᴛᴡᴏʀᴋ 𝗟ɪɴᴋ 𝗦ᴛᴀʙʟᴇ\n│ ▰▰▰▰▰▰▰▱▱▱  72%\n╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━╯",
        "╭━━━━━━━━〔 ⚡ 𝗦ʏsᴛᴇᴍ 𝗖ᴏʀᴇ 〕━━━━━━━━╮\n│ ◉ 𝗔ʀᴄ 𝗖ᴏʀᴇ 𝗢ɴʟɪɴᴇ\n│ ▰▰▰▰▰▰▰▰▰▰  100%\n╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━╯",
    ]
    msg = None
    for source in _pfp_sources():
        try:
            msg = await update.message.reply_photo(photo=source, caption=frames[0])
            for frame in frames[1:]:
                await asyncio.sleep(0.18)
                await msg.edit_caption(caption=frame)
            break
        except Exception:
            msg = None
    if msg is None:
        try:
            msg = await update.message.reply_text(frames[0])
            for frame in frames[1:]:
                await asyncio.sleep(0.18)
                await msg.edit_text(frame)
        except Exception:
            msg = None

    results = []
    for bot in list(bots):
        started = time.perf_counter()
        try:
            me = await bot.get_me()
            latency = max(1, int((time.perf_counter() - started) * 1000))
            label = f"@{me.username}" if me.username else (me.first_name or str(me.id))
            results.append(f"│ 🟢 {label} » {latency}ms")
        except Exception as exc:
            latency = int((time.perf_counter() - started) * 1000)
            results.append(f"│ 🔴 bot » failed {latency}ms ({str(exc)[:45]})")

    active = len(bots)
    text = (
        "╭━━━━━━━━〔 ❄️ 𝗬ᴜ𝗧ᴀ 〕━━━━━━━━╮\n"
        f"│ 🟢 𝗦ᴇssɪᴏɴs » {active} 𝗔ᴄᴛɪᴠᴇ\n"
        "│\n"
        "│ 𝗕ᴏᴛ 𝗥ᴇsᴘᴏɴsᴇ 𝗧ɪᴍᴇ:\n"
        + ("\n".join(results) if results else "│ 🟠 No configured bot is ready.") +
        "\n│\n"
        "╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━╯\n"
        "──〔  𝗬ᴜ𝗧ᴀ  〕───"
    )
    if msg:
        try:
            await msg.delete()
        except Exception:
            pass
    await _send_pfp_box(update, text)

