#              NC COMMANDS (-nc1 — -nc10)


# ═══════════════════════════════════════════════


def _make_nc_cmd(nc_num: int):


    @only_owner


    async def nc_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):


        await _sessy_action_animation(update, f"NC{nc_num} Started", "🌺")

        if not context.args:


            return await _send_pfp_box(update, f"⚡ 𝗨ꜱᴀɢᴇ » nc{nc_num} ‹ɴᴀᴍᴇ› 🌺")


        base = stylize_name(" ".join(context.args))


        chat_id = update.message.chat_id


        texts = NC_TEXTS_MAP[nc_num]


        nc_tasks[nc_num].setdefault(chat_id, {})


        for bot in bots:


            key = getattr(bot, "token", str(id(bot)))


            if key not in nc_tasks[nc_num][chat_id]:


                task = asyncio.create_task(


                    nc_bot_loop(bot, chat_id, base, texts, len(nc_tasks[nc_num][chat_id]))


                )


                nc_tasks[nc_num][chat_id][key] = task


        await _send_pfp_box(update, f"╭──〔 🫧 𝗡ᴄ{nc_num} 〕──╮\n│ 🟢 𝗦ᴛᴀᴛᴜs » 𝗔ᴄᴛɪᴠᴇ\n│ 🤖 𝗕ᴏᴛs » {len(bots)} 𝐋ᴏᴀᴅᴇᴅ\n│ 💬 𝐂ʜᴀᴛ » {update.effective_chat.title or update.effective_chat.id}\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


    nc_cmd.__name__ = f"nc{nc_num}_cmd"


    return nc_cmd


nc1_cmd  = _make_nc_cmd(1)


nc2_cmd  = _make_nc_cmd(2)


nc3_cmd  = _make_nc_cmd(3)


nc4_cmd  = _make_nc_cmd(4)


nc5_cmd  = _make_nc_cmd(5)


nc6_cmd  = _make_nc_cmd(6)


nc7_cmd  = _make_nc_cmd(7)


nc8_cmd  = _make_nc_cmd(8)


nc9_cmd  = _make_nc_cmd(9)


nc10_cmd = _make_nc_cmd(10)


@only_owner
async def stopnc(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _sessy_action_animation(update, "NC Stop", "🛑")
    chat_id = update.message.chat_id
    to_cancel = []
    for nc_num in range(1, 11):
        tasks = nc_tasks[nc_num].pop(chat_id, None)
        if tasks:
            to_cancel.extend(t for t in tasks.values() if t)
    _boost_state.pop(chat_id, None)
    _last_set_title.pop(chat_id, None)
    for task in to_cancel:
        if not task.done():
            task.cancel()
    if to_cancel:
        await asyncio.gather(*to_cancel, return_exceptions=True)
    await _send_pfp_box(update, "╭──〔 🛑 𝗡𝗖 𝗦ᴛᴏᴘ 〕──╮\n│ 🔴 𝗦ᴛᴀᴛᴜs » 𝗦ᴛᴏᴘᴘᴇᴅ\n│ 🤖 𝗟ᴏᴏᴘs » 𝗔ʟʟ 𝗖ʟᴇᴀʀᴇᴅ\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯" if to_cancel else "╭──〔 🫠 𝗡𝗖 𝗦ᴛᴏᴘ 〕──╮\n│ 𝗡ᴏ 𝗔ᴄᴛɪᴠᴇ 𝗟ᴏᴏᴘs 𝗙ᴏᴜɴᴅ\n╰──────────────────╯")


# Individual NC stop controls. These only cancel the selected NC task set.
def _make_stopnc_cmd(nc_num: int):
    @only_owner
    async def stopnc_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
        chat_id = update.message.chat_id
        tasks = nc_tasks[nc_num].pop(chat_id, None)
        to_cancel = list(tasks.values()) if tasks else []
        for task in to_cancel:
            if task and not task.done():
                task.cancel()
        if to_cancel:
            await asyncio.gather(*to_cancel, return_exceptions=True)
        status = "𝐒ᴛᴏᴘᴘᴇᴅ" if to_cancel else "𝗡ᴏ 𝗔ᴄᴛɪᴠᴇ 𝗟ᴏᴏᴘs"
        await _send_pfp_box(update, f"╭──〔 🛑 𝐍𝐂{nc_num} 𝗦ᴛᴏᴘ 〕──╮\n│ 🔴 𝗦ᴛᴀᴛᴜs » {status}\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")
    stopnc_cmd.__name__ = f"stopnc{nc_num}_cmd"
    return stopnc_cmd

stopnc1_cmd = _make_stopnc_cmd(1)
stopnc2_cmd = _make_stopnc_cmd(2)
