def _make_slide_cmd(slide_num: int):


    @only_owner


    async def slide_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):


        await _sessy_action_animation(update, f"Slide{slide_num} Started", "🎭")

        if not update.message.reply_to_message:


            return await _send_pfp_box(update, f"🔥 𝗥ᴇᴘʟʏ 𝗧ᴏ 𝗔 𝗨ꜱᴇʀ ꜰᴏʀ 𝗧ᴀʀɢᴇᴛ 𝗦ʟɪᴅᴇ {slide_num} ")


        target_user = update.message.reply_to_message.from_user


        slide_targets_map[slide_num].add(target_user.id)


        name = f"@{target_user.username}" if target_user.username else target_user.first_name


        await _send_pfp_box(update, f"╭──〔 🎭 𝐒ʟɪᴅᴇ{slide_num} 〕──╮\n│ 🟢 𝗦ᴛᴀᴛᴜs » 𝗔ᴄᴛɪᴠᴇ\n│ 🎯 𝐓ᴀʀɢᴇᴛ » {name}\n╰────────────────────╯\n│\n│        ──〔  𝐘ᴜ𝐓ᴀ  〕───\n╰────────────────────╯")


    slide_cmd.__name__ = f"slide{slide_num}_cmd"


    return slide_cmd


def _make_stopslide_cmd(slide_num: int):
    @only_owner
    async def stopslide_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
        await _sessy_action_animation(update, f"Slide{slide_num} Stop", "🛑")
        chat_id = update.message.chat_id
        slide_targets_map[slide_num].clear()
        keys = [k for k in slide_reply_tasks[slide_num] if k.startswith(f"{chat_id}_")]
        to_cancel = [slide_reply_tasks[slide_num].pop(k, None) for k in keys]
        to_cancel = [t for t in to_cancel if t]
        for task in to_cancel:
            if not task.done():
                task.cancel()
        if to_cancel:
            await asyncio.gather(*to_cancel, return_exceptions=True)
        await _send_pfp_box(update, f"╭──〔 🛑 𝐒ʟɪᴅᴇ{slide_num} 〕──╮\n│ 🔴 𝗦ᴛᴀᴛᴜs » 𝗦ᴛᴏᴘᴘᴇᴅ\n│ 🎯 𝐓ᴀʀɢᴇᴛ » 𝗖ʟᴇᴀʀᴇᴅ\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")
    stopslide_cmd.__name__ = f"stopslide{slide_num}_cmd"
    return stopslide_cmd

slide1_cmd  = _make_slide_cmd(1)


