def _make_spam_cmd(spam_num: int):


    @only_owner


    async def spam_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):


        await _sessy_action_animation(update, f"Spam{spam_num} Started", "🌪️")

        chat_id = update.message.chat_id


        extra = " ".join(context.args) if context.args else ""


        texts = SPAM_TEXTS_MAP[spam_num]


        if chat_id in spam_tasks[spam_num]:


            spam_tasks[spam_num][chat_id].cancel()


        task = asyncio.create_task(spam_loop(chat_id, texts, extra))


        spam_tasks[spam_num][chat_id] = task


        await _send_pfp_box(update, f"╭──〔 🫧 𝗦ᴘᴀᴍ{spam_num} 〕──╮\n│ 🟢 𝗦ᴛᴀᴛᴜs » 𝗔ᴄᴛɪᴠᴇ\n│ 💬 𝗖ʜᴀᴛ » {update.effective_chat.title or update.effective_chat.id}\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


    spam_cmd.__name__ = f"spam{spam_num}_cmd"


    return spam_cmd


def _make_stopspam_cmd(spam_num: int):
    @only_owner
    async def stopspam_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
        await _sessy_action_animation(update, f"Spam{spam_num} Stop", "🛑")
        chat_id = update.message.chat_id
        task = spam_tasks[spam_num].pop(chat_id, None)
        if task and not task.done():
            task.cancel()
            await asyncio.gather(task, return_exceptions=True)
        status = "𝐒ᴛᴏᴘᴘᴇᴅ" if task else "𝗡ᴏ 𝗔ᴄᴛɪᴠᴇ 𝗧ᴀsᴋ"
        await _send_pfp_box(update, f"╭──〔 🛑 𝗦ᴘᴀᴍ{spam_num} 〕──╮\n│ 🔴 𝐒ᴛᴀᴛᴜs » {status}\n│ 🧹 𝐂ʜᴀᴛ 𝗧ᴀsᴋ » 𝗖ʟᴇᴀʀᴇᴅ\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")
    stopspam_cmd.__name__ = f"stopspam{spam_num}_cmd"
    return stopspam_cmd


@only_owner
async def stopspam(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Stop every spam slot for the current chat."""
    await _sessy_action_animation(update, "Spam Stop All", "🛑")
    chat_id = update.message.chat_id
    to_cancel = []
    for n in range(1, 5):
        task = spam_tasks[n].pop(chat_id, None)
        if task:
            to_cancel.append(task)
    for task in to_cancel:
        if not task.done():
            task.cancel()
    if to_cancel:
        await asyncio.gather(*to_cancel, return_exceptions=True)
    await _send_pfp_box(update, "╭──〔 🛑 𝗦ᴘᴀᴍ 𝗦ᴛᴏᴘ 〕──╮\n│ 🔴 𝗦ᴛᴀᴛᴜs » 𝗔ʟʟ 𝗦ᴛᴏᴘᴘᴇᴅ\n│ 🧹 𝗟ᴏᴏᴘs » 𝗖ʟᴇᴀʀᴇᴅ\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


spam1_cmd  = _make_spam_cmd(1)


