@only_owner


async def targetslide(update: Update, context: ContextTypes.DEFAULT_TYPE):


    if update.message.reply_to_message:


        slide_targets.add(update.message.reply_to_message.from_user.id)


        await _send_pfp_box(update, "╭──〔 🎯 𝗧ᴀʀɢᴇᴛ 〕──╮\n│ 🟢 𝗦ᴛᴀᴛᴜs » 𝗔ᴄᴛɪᴠᴇ\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


    else:


        await _send_pfp_box(update, "⚠️ Reply to a user to target them.")


@only_owner
async def stopslide(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    if update.message.reply_to_message:
        slide_targets.discard(update.message.reply_to_message.from_user.id)
    else:
        slide_targets.clear()
    task = slide_loop_tasks.pop(chat_id, None)
    if task and not task.done():
        task.cancel()
        await asyncio.gather(task, return_exceptions=True)
    to_cancel = []
    for n in range(1, 5):
        to_cancel.extend(slide_reply_tasks[n].values())
        slide_reply_tasks[n].clear()
    for task in to_cancel:
        if task and not task.done():
            task.cancel()
    if to_cancel:
        await asyncio.gather(*to_cancel, return_exceptions=True)
    await _send_pfp_box(update, "╭──〔 🛑 𝗧ᴀʀɢᴇᴛ 〕──╮\n│ 🔴 𝗦ᴛᴀᴛᴜs » 𝗦ᴛᴏᴘᴘᴇᴅ\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")

