#              PHOTO NC COMMANDS


# ═══════════════════════════════════════════════


@only_owner


async def pfp_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):


    if not update.message.reply_to_message or not update.message.reply_to_message.photo:


        return await _send_pfp_box(update, "💾 𝗥ᴇᴘʟʏ 𝗧ᴏ 𝗔 𝗣ʜᴏᴛᴏ 𝗧ᴏ 𝗦ᴀᴠᴇ 𝗜ᴛ")


    chat_id = update.message.chat_id


    photo_store.setdefault(chat_id, [])


    if len(photo_store[chat_id]) >= MAX_PHOTOS:


        return await _send_pfp_box(update, 


            f"🔥 𝗠ᴀx{MAX_PHOTOS} 🫧 𝗣ʜᴏᴛᴏ 𝗥ᴇᴀᴄʜᴇᴅ 𝗗ᴇʟ 𝗢ɴᴇ 𝗧ᴏ 𝗦ᴀᴠᴇ 𝗧ʜɪꜱ 💾"


        )


    photo = update.message.reply_to_message.photo[-1]


    fid = photo.file_unique_id


    if any(p[0] == fid for p in photo_store[chat_id]):


        return await _send_pfp_box(update, "💾 𝗔ʟʀᴇᴀᴅʏ 𝗦ᴀᴠᴇᴅ")


    try:


        file = await context.bot.get_file(photo.file_id)


        data = bytes(await file.download_as_bytearray())


        photo_store[chat_id].append((fid, data))


        count = len(photo_store[chat_id])


        await _send_pfp_box(update, f"╭──〔 💾 𝗣ʜᴏᴛᴏ 〕──╮\n│ 🟢 𝗦ᴛᴀᴛᴜs » 𝗦ᴀᴠᴇᴅ\n│ 📦 𝗦ᴛᴏʀᴀɢᴇ » {count}/{MAX_PHOTOS}\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


    except Exception as e:


        await _send_pfp_box(update, f"⚠️ 𝗘ʀʀᴏʀ » {e} ")


@only_owner


async def dps_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):


    if not update.message.reply_to_message or not update.message.reply_to_message.photo:


        return await _send_pfp_box(update, "🗑️ 𝗥ᴇᴘʟʏ 𝗧ᴏ 𝗔 𝗣ʜᴏᴛᴏ 𝗧ᴏ 𝗗ᴇʟᴇᴛᴇ 𝐈ᴛ")


    chat_id = update.message.chat_id


    fid = update.message.reply_to_message.photo[-1].file_unique_id


    store = photo_store.get(chat_id, [])


    new_store = [p for p in store if p[0] != fid]


    if len(new_store) == len(store):


        return await _send_pfp_box(update, "🔍 𝗣ʜᴏᴛᴏ 𝗡ᴏᴛ 𝗙ᴏᴜɴᴅ")


    photo_store[chat_id] = new_store


    await _send_pfp_box(update, f"╭──〔 🗑️ 𝗣ʜᴏᴛᴏ 〕──╮\n│ 🔴 𝗦ᴛᴀᴛᴜs » 𝗗ᴇʟᴇᴛᴇᴅ\n│ 📦 𝗥ᴇᴍᴀɪɴ » {len(new_store)}/{MAX_PHOTOS}\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


@only_owner


async def ps_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):


    chat_id = update.message.chat_id


    store = photo_store.get(chat_id, [])


    if len(store) < MIN_PHOTOS:


        return await _send_pfp_box(update, 


            f"⚠️ 𝗡ᴇᴇᴅ 𝗔ᴛ 𝗟ᴇᴀꜱᴛ{MIN_PHOTOS} 💾 𝗣ʜᴏᴛᴏ 𝗦ᴀᴠᴇᴅ [{len(store)}/{MIN_PHOTOS}] "


        )


    if chat_id in photo_loop_tasks:


        photo_loop_tasks[chat_id].cancel()


    task = asyncio.create_task(photo_loop(chat_id))


    photo_loop_tasks[chat_id] = task


    await _send_pfp_box(update, f"╭──〔 🔄 𝗣ʜᴏᴛᴏ 𝗟ᴏᴏᴘ 〕──╮\n│ 🟢 𝗦ᴛᴀᴛᴜs » 𝗔ᴄᴛɪᴠᴇ\n│ 📸 𝗣ʜᴏᴛᴏs » {len(store)}\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


@only_owner


async def pfs_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):


    chat_id = update.message.chat_id


    if chat_id in photo_loop_tasks:


        photo_loop_tasks[chat_id].cancel()


        del photo_loop_tasks[chat_id]


        await _send_pfp_box(update, "╭──〔 🛑 𝗣ʜᴏᴛᴏ 𝗟ᴏᴏᴘ 〕──╮\n│ 🔴 𝗦ᴛᴀᴛᴜs » 𝗦ᴛᴏᴘᴘᴇᴅ\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


    else:


        await _send_pfp_box(update, "🫠 𝗡ᴏ 𝗣ʜᴏᴛᴏ 𝗟ᴏᴏᴘ 𝗔ᴄᴛɪᴠᴇ")


# ═══════════════════════════════════════════════


async def _sudo_success_animation(update: Update, name: str, added: bool = True):
    """Short PFP-backed Sudo status animation."""
    if not update.message:
        return
    action = "𝗔ᴅᴅɪɴɢ" if added else "𝗥ᴇᴍᴏᴠɪɴɢ"
    final = "𝗦ᴜᴅᴏ 𝗔ᴄᴄᴇss 𝗚ʀᴀɴᴛᴇᴅ" if added else "𝗦ᴜᴅᴏ 𝗔ᴄᴄᴇss 𝗥ᴇᴠᴏᴋᴇᴅ"
    frames = [
        f"╭━━━━━━━━〔 👑 𝗦ᴜᴅᴏ 〕━━━━━━━━╮\n│ ⏳ {action} 𝗔ᴄᴄᴇss...\n│ 👤 𝗨sᴇʀ » {name}\n╰━━━━━━━━━━━━━━━━━━━━━━━━╯",
        f"╭━━━━━━━━〔 👑 𝗦ᴜᴅᴏ 〕━━━━━━━━╮\n│ 🔐 𝗩ᴇʀɪғʏɪɴɢ 𝗣ᴇʀᴍɪssɪᴏɴs...\n│ 👤 𝗨sᴇʀ » {name}\n╰━━━━━━━━━━━━━━━━━━━━━━━━╯",
        f"╭━━━━━━━━〔 👑 𝗦ᴜᴅᴏ 〕━━━━━━━━╮\n│ 🟢 {final}\n│ 👤 𝗨sᴇʀ » {name}\n│ 🫧 𝗬ᴜ𝗧ᴀ • 𝗔ᴜᴛʜ 𝗦ʏsᴛᴇᴍ\n╰━━━━━━━━━━━━━━━━━━━━━━━━╯",
    ]
    for source in _pfp_sources():
        try:
            msg = await update.message.reply_photo(photo=source, caption=frames[0])
            for frame in frames[1:]:
                await asyncio.sleep(0.25)
                await msg.edit_caption(caption=frame)
            return
        except Exception:
            continue
    msg = await update.message.reply_text(frames[0])
    for frame in frames[1:]:
        await asyncio.sleep(0.25)
        try:
            await msg.edit_text(frame)
        except Exception:
            break


