@only_owner


async def addsudo(update: Update, context: ContextTypes.DEFAULT_TYPE):


    if update.message.reply_to_message:


        user = update.message.reply_to_message.from_user


        uid = user.id


        name = f"@{user.username}" if user.username else user.first_name


        SUDO_USERS.add(uid)


        SUDO_NAMES[uid] = name


        save_sudo()


        await _sudo_success_animation(update, name, added=True)


    else:


        await _send_pfp_box(update, "➕ 𝗥ᴇᴘʟʏ 𝗧ᴏ 𝗔 𝗨ꜱᴇʀ 𝗧ᴏ 𝗔ᴅᴅ 𝗧ʜᴇᴍ")


@only_owner


async def delsudo(update: Update, context: ContextTypes.DEFAULT_TYPE):


    if update.message.reply_to_message:


        user = update.message.reply_to_message.from_user


        uid = user.id


        name = f"@{user.username}" if user.username else user.first_name


        if uid in SUDO_USERS:


            SUDO_USERS.remove(uid)


            save_sudo()


            await _sudo_success_animation(update, name, added=False)


        else:


            await _send_pfp_box(update, "⚠️ 𝗨ꜱᴇʀ 𝗡ᴏᴛ 𝗜ɴ 𝗦ᴜᴅᴏ 𝗟ɪꜱᴛ")


    else:


        await _send_pfp_box(update, "➖ 𝗥ᴇᴘʟʏ 𝗧ᴏ 𝗔 𝗨ꜱᴇʀ 𝗧ᴏ 𝗥ᴇᴍᴏᴠᴇ 𝗧ʜᴇᴍ")


@only_owner


async def listsudo(update: Update, context: ContextTypes.DEFAULT_TYPE):


    await _sessy_action_animation(update, "Sudo List", "👑")

    if not SUDO_USERS:


        return await _send_pfp_box(update, "⚠️ 𝗡ᴏ 𝗦ᴜᴅᴏ 𝗨ꜱᴇʀ\n\n𝗡ᴏᴏɴᴇ")


    lines = []


    for uid in SUDO_USERS:


        name = SUDO_NAMES.get(uid, str(uid))


        lines.append(name)


    await _send_pfp_box(update, "╭──〔 👑 𝗦ᴜᴅᴏ 𝗟ɪsᴛ 〕──╮\n│\n" + "\n".join(f"│  {i}. 👤 {name}" for i, name in enumerate(lines, 1)) + "\n│\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


