async def _find_loaded_bot(username: str):
    wanted = username.lstrip("@").casefold()
    for b in bots:
        try:
            me = await b.get_me()
            if (me.username or "").casefold() == wanted:
                return b, me
        except Exception:
            continue
    return None, None

@only_owner
async def addbot_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not context.args:
        return await _send_pfp_box(update, 
            "╭──〔 🤖 𝗔ᴅᴅ𝗕ᴏᴛ 〕──╮\n│ ℹ️ 𝗨sᴀɢᴇ » -AddBot @username\n│\n│ 𝗡ᴏᴛᴇ » 𝗕ᴏᴛ 𝗔ᴘɪ ᴄᴀɴɴᴏᴛ ɪɴᴠɪᴛᴇ ᴀɴᴏᴛʜᴇʀ 𝗕ᴏᴛ.\n│ 𝗜ɴᴠɪᴛᴇ ɪᴛ ᴍᴀɴᴜᴀʟʟʏ, ᴛʜᴇɴ ᴜsᴇ -PromoteBot.\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯"
        )
    username = context.args[0]
    bot, me = await _find_loaded_bot(username)
    if not bot:
        return await _send_pfp_box(update, 
            f"╭──〔 🤖 𝗔ᴅᴅ𝗕ᴏᴛ 〕──╮\n│ ⚠️ 𝗕ᴏᴛ » {username}\n│ 🔴 𝗦ᴛᴀᴛᴜs » 𝗡ᴏᴛ 𝗟ᴏᴀᴅᴇᴅ\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯"
        )
    try:
        member = await bot.get_chat_member(update.effective_chat.id, me.id)
        present = member.status not in ("left", "kicked")
    except Exception:
        present = False
    state = "𝗔ʟʀᴇᴀᴅʏ 𝗜ɴ 𝗚𝗖" if present else "𝗡ᴏᴛ 𝗜ɴ 𝗚𝗖"
    return await _send_pfp_box(update, 
        f"╭──〔 🤖 𝗔ᴅᴅ𝗕ᴏᴛ 〕──╮\n│ 🟢 𝐁ᴏᴛ » @{me.username}\n│ 📍 𝗚𝗖 » {update.effective_chat.title or update.effective_chat.id}\n│ 📊 𝗦ᴛᴀᴛᴜs » {state}\n│\n│ ℹ️ 𝗜ɴᴠɪᴛᴇ 𝗠ᴀɴᴜᴀʟʟʏ ɪғ ɴᴇᴇᴅᴇᴅ.\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯"
    )

@only_owner
async def promotebot_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _sessy_action_animation(update, "Bot Promote", "👑")
    if not context.args:
        return await _send_pfp_box(update, 
            "╭──〔 👑 𝗣ʀᴏᴍᴏᴛᴇ𝗕ᴏᴛ 〕──╮\n│ ℹ️ 𝗨sᴀɢᴇ » -PromoteBot @username\n│ 🛡️ 𝗦ᴄᴏᴘᴇ » 𝗢ɴᴇ 𝗦ᴇʟᴇᴄᴛᴇᴅ 𝗕ᴏᴛ\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯"
        )
    username = context.args[0]
    target_bot, me = await _find_loaded_bot(username)
    if not target_bot:
        return await _send_pfp_box(update, 
            f"╭──〔 👑 𝗣ʀᴏᴍᴏᴛᴇ𝗕ᴏᴛ 〕──╮\n│ 🔴 𝗕ᴏᴛ » {username}\n│ ⚠️ 𝗦ᴛᴀᴛᴜs » 𝗡ᴏᴛ 𝗟ᴏᴀᴅᴇᴅ\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯"
        )
    try:
        member = await target_bot.get_chat_member(update.effective_chat.id, me.id)
        if member.status in ("left", "kicked"):
            raise RuntimeError("Bot is not a member of this group")
        if not bots:
            raise RuntimeError("No master bot loaded")
        await bots[0].promote_chat_member(
            chat_id=update.effective_chat.id,
            user_id=me.id,
            can_manage_chat=True,
            can_change_info=True,
            can_post_messages=True,
            can_edit_messages=True,
            can_delete_messages=True,
            can_invite_users=True,
            can_restrict_members=True,
            can_pin_messages=True,
            can_manage_video_chats=True,
            can_promote_members=False,
        )
        result = "𝗣ʀᴏᴍᴏᴛᴇᴅ"
    except Exception as exc:
        result = f"𝗙ᴀɪʟᴇᴅ · {str(exc)[:90]}"
    return await _send_pfp_box(update, 
        f"╭──〔 👑 𝗣ʀᴏᴍᴏᴛᴇ𝗕ᴏᴛ 〕──╮\n│ 🤖 𝗕ᴏᴛ » @{me.username}\n│ 💬 𝗚𝗖 » {update.effective_chat.title or update.effective_chat.id}\n│ 📊 𝐒ᴛᴀᴛᴜs » {result}\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯"
    )


@only_owner
async def promote_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Promote a normal group member to admin. Prefer replying to their message."""
    await _sessy_action_animation(update, "Member Promote", "👑")
    target_id = None
    target_label = None
    if update.message and update.message.reply_to_message:
        target = update.message.reply_to_message.from_user
        if target:
            target_id = target.id
            target_label = f"@{target.username}" if target.username else target.full_name
    elif context.args and context.args[0].isdigit():
        target_id = int(context.args[0])
        target_label = str(target_id)
    elif context.args and context.args[0].startswith("@"):
        return await _send_pfp_box(update, "⚠️ Direct @username lookup is not available through the Telegram Bot API here. Reply to that user's message with √promote, or use the numeric ID.")
    else:
        return await _send_pfp_box(update, 
            "╭──〔 👑 𝗣ʀᴏᴍᴏᴛᴇ 〕──╮\n"
            "│ 𝗥ᴇᴘʟʏ 𝗧ᴏ 𝗧ʜᴇ 𝗨sᴇʀ's 𝗠ᴇssᴀɢᴇ 𝗪ɪᴛʜ √promote\n"
            "│ 𝗢ʀ 𝗨sᴇ √promote <user_id>\n"
            "│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n"
            "╰────────────────────╯"
        )
    try:
        # Bot must already be an administrator with permission to promote members.
        me = await context.bot.get_me()
        bot_member = await context.bot.get_chat_member(update.effective_chat.id, me.id)
        if bot_member.status not in ("administrator", "creator"):
            raise RuntimeError("This bot is not an admin in this group")
        if bot_member.status == "administrator" and not getattr(bot_member, "can_promote_members", False):
            raise RuntimeError("This bot has no permission to add admins")
        await context.bot.promote_chat_member(
            chat_id=update.effective_chat.id,
            user_id=target_id,
            can_manage_chat=False,
            can_change_info=False,
            can_post_messages=True,
            can_edit_messages=False,
            can_delete_messages=False,
            can_invite_users=True,
            can_restrict_members=False,
            can_pin_messages=True,
            can_manage_video_chats=False,
            can_promote_members=False,
        )
        result = "🟢 𝗣ʀᴏᴍᴏᴛᴇᴅ"
    except Exception as exc:
        result = f"🔴 𝗙ᴀɪʟᴇᴅ · {str(exc)[:90]}"
    return await _send_pfp_box(update, 
        f"╭──〔 👑 𝗣ʀᴏᴍᴏᴛᴇ 〕──╮\n│ 👤 𝐔𝗨sᴇʀ » {target_label}\n│ 📊 𝗦ᴛᴀᴛᴜs » {result}\n│ 💬 𝗚𝗖 » {update.effective_chat.title or update.effective_chat.id}\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯"
    )


