            "│ ᴛʜᴇɴ 𝐮sᴇ √id ᴛᴏ ɢᴇᴛ ᴛʜᴇ 𝗜ᴅ.\n"
            "│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n"
