@only_owner
async def status_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show a compact dashboard of service, bots, known chats and active tasks."""
    await _sessy_action_animation(update, "Status Scan", "📊")
    now = time.time()

    # Process uptime: this is the most reliable "active since" value.
    started = globals().get("SERVICE_STARTED_AT", now)
    total_uptime = max(0, int(now - started))
    days, rem = divmod(total_uptime, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, seconds = divmod(rem, 60)
    uptime = f"{days}d {hours}h {minutes}m {seconds}s"

    # Collect chats known from bot activity.
    known = {}
    for bot_id, chats in bot_chat_registry.items():
        for chat_id, info in chats.items():
            if chat_id >= 0:
                continue
            item = known.setdefault(chat_id, {
                "title": info.get("title") or str(chat_id),
                "username": info.get("username"),
                "bots": set(),
                "last_seen": 0,
            })
            item["bots"].add(bot_id)
            item["last_seen"] = max(item["last_seen"], info.get("last_seen", 0))

    # Add chats that currently have tracked tasks even if the registry has not
    # received a fresh message for them yet.
    active = {}
    def active_chat(chat_id, kind, bot_count=0):
        if chat_id >= 0:
            return
        item = active.setdefault(chat_id, {"tasks": [], "bots": 0})
        if kind not in item["tasks"]:
            item["tasks"].append(kind)
        item["bots"] = max(item["bots"], bot_count)

    for nc_num in range(1, 11):
        for chat_id, tasks in nc_tasks[nc_num].items():
            live = [t for t in tasks.values() if t and not t.done()]
            if live:
                active_chat(chat_id, f"NC{nc_num}", len(live))

    for slide_num in range(1, 5):
        for chat_id, tasks in slide_tasks[slide_num].items():
            live = [t for t in tasks.values() if t and not t.done()]
            if live:
                active_chat(chat_id, f"Slide{slide_num}", len(live))

    for spam_num in range(1, 5):
        for chat_id, task in spam_tasks[spam_num].items():
            if task and not task.done():
                active_chat(chat_id, f"Spam{spam_num}")

    for chat_id, task in slide_loop_tasks.items():
        if task and not task.done():
            active_chat(chat_id, "TargetSlide")

    for chat_id, task in photo_loop_tasks.items():
        if task and not task.done():
            active_chat(chat_id, "PfpLoop")

    # Merge active information into known groups.
    for chat_id, item in active.items():
        known.setdefault(chat_id, {
            "title": str(chat_id), "username": None, "bots": set(), "last_seen": 0
        })

    total_known = len(known)
    total_active = len(active)
    total_active_tasks = sum(len(v["tasks"]) for v in active.values())
    total_tracked_bots = len(bots)

    lines = [
        "╭━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━╮",
        "│      🫧 𝗬ᴜ𝗧ᴀ 𝗦ᴛᴀᴛᴜs 𝗗ᴀsʜʙᴏᴀʀᴅ      │",
        "╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━╯",
        "",
        f"🟢 𝗦ᴛᴀᴛᴜs       » 𝗔ᴄᴛɪᴠᴇ",
        f"⏳ 𝗨ᴘᴛɪᴍᴇ       » {uptime}",
        f"🤖 𝗕ᴏᴛs          » {total_tracked_bots} 𝗟ᴏᴀᴅᴇᴅ",
        f"🌐 𝗚ᴄs           » {total_known} 𝗞ɴᴏᴡɴ",
        f"🔥 𝗔ᴄᴛɪᴠᴇ 𝗚ᴄs   » {total_active}",
        f"⚙️ 𝗔ᴄᴛɪᴠᴇ 𝗠ᴏᴅᴇs » {total_active_tasks}",
        "",
        "╭──────〔 🌐 𝗚ᴄ 𝗢ᴠᴇʀᴠɪᴇᴡ 〕──────╮",
    ]

    if known:
        # Most recently seen first.
        ordered = sorted(known.items(), key=lambda x: x[1].get("last_seen", 0), reverse=True)
        for idx, (chat_id, info) in enumerate(ordered, 1):
            title = str(info.get("title") or chat_id).replace("\n", " ")[:42]
            bot_seen = len(info.get("bots", set()))
            active_info = active.get(chat_id, {})
            task_names = active_info.get("tasks", [])
            task_text = ", ".join(task_names) if task_names else "Idle"
            active_bots = active_info.get("bots", 0)
            if active_bots:
                bot_text = f"{active_bots} active bot(s)"
            else:
                bot_text = f"{bot_seen} seen bot(s)"
            lines += [
                "│",
                f"│  {idx}. 🏷️ {title}",
                f"│     🆔 {chat_id}",
                f"│     🤖 {bot_text}",
                f"│     ⚙️ {task_text}",
            ]
    else:
        lines.append("│  🫠 𝗡ᴏ 𝗚ᴄ 𝗗ᴀᴛᴀ 𝗦ᴇᴇɴ 𝗬ᴇᴛ")

    lines += [
        "│",
        "╰────────────────────────────────╯",
        "",
        "ℹ️ 𝗞ɴᴏᴡɴ = bots have seen the chat.",
        "ℹ️ 𝗔ᴄᴛɪᴠᴇ = tracked tasks currently running.",
        "",
        "│        ──〔  𝗬ᴜ𝗧ᴀ  〕───",
        "╰────────────────────────────────╯",
    ]
    await _send_pfp_box(update, "\n".join(lines))


@only_owner


async def stopall(update: Update, context: ContextTypes.DEFAULT_TYPE):


    await _sessy_action_animation(update, "Stop All", "🛑")

    chat_id = update.message.chat_id


    to_cancel: list = []


    for nc_num in range(1, 11):


        if chat_id in nc_tasks[nc_num]:


            to_cancel.extend(nc_tasks[nc_num][chat_id].values())


            del nc_tasks[nc_num][chat_id]


    for slide_num in range(1, 5):


        if chat_id in slide_tasks[slide_num]:


            to_cancel.extend(slide_tasks[slide_num][chat_id].values())


            del slide_tasks[slide_num][chat_id]


    for spam_num in range(1, 5):


        if chat_id in spam_tasks[spam_num]:


            to_cancel.append(spam_tasks[spam_num][chat_id])


            del spam_tasks[spam_num][chat_id]


    if chat_id in slide_loop_tasks:


        to_cancel.append(slide_loop_tasks[chat_id])


        del slide_loop_tasks[chat_id]


    for slide_num in range(1, 5):


        keys_to_del = [k for k in slide_reply_tasks[slide_num] if k.startswith(f"{chat_id}_")]


        for k in keys_to_del:


            to_cancel.append(slide_reply_tasks[slide_num][k])


            del slide_reply_tasks[slide_num][k]


    if chat_id in photo_loop_tasks:


        to_cancel.append(photo_loop_tasks[chat_id])


        del photo_loop_tasks[chat_id]


    _boost_state.pop(chat_id, None)


    _last_set_title.pop(chat_id, None)


    mute_targets.pop(chat_id, None)
    slide_targets.clear()
    slidespam_targets.clear()
    for _n in range(1, 5):
        slide_targets_map[_n].clear()


    # Cancel every collected task and wait for cancellation to finish.
    for t in to_cancel:
        if t and not t.done():
            t.cancel()


    if to_cancel:
        await asyncio.gather(*to_cancel, return_exceptions=True)


    await _send_pfp_box(update, "╭──〔 🛑 𝗦ᴛᴏᴘ 𝗔ʟʟ 〕──╮\n│ 🔴 𝗦ᴛᴀᴛᴜs » 𝗖ʟᴇᴀʀᴇᴅ\n│ 💬 𝗦ᴄᴏᴘᴇ » 𝗧ʜɪs 𝗖ʜᴀᴛ\n╰────────────────────╯\n│\n│        ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")


# ═══════════════════════════════════════════════


#              AUTO REMOVE (foreign bots)


# ═══════════════════════════════════════════════


async def autoremove_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):


    if not update.chat_member:


        return


    chat_id = update.chat_member.chat.id


    if chat_id not in autoremove_chats:


        return


    new_member = update.chat_member.new_chat_member


    old_member = update.chat_member.old_chat_member


    joined_statuses = ("member", "administrator", "creator", "restricted")


    if new_member.status not in joined_statuses:


        return


    if old_member.status in joined_statuses:


        return


    user = new_member.user


    if not user.is_bot:


        return


    if user.id in our_bot_ids:


        return


    candidates = []


    if getattr(context, "bot", None):
        candidates.append(context.bot)


    candidates.extend(bots)
    seen = set()


    for bot in candidates:
        if id(bot) in seen:
            continue
        seen.add(id(bot))
        try:
            me = await bot.get_me()
            if me.id == user.id:
                continue
            member = await bot.get_chat_member(chat_id, me.id)
            if member.status not in ("administrator", "creator"):
                continue
            await bot.ban_chat_member(chat_id=chat_id, user_id=user.id)
            await asyncio.sleep(0.15)
            try:
                await bot.unban_chat_member(chat_id=chat_id, user_id=user.id)
            except Exception:
                pass
            print(f"[YUTA AUTOREMOVE] Removed foreign bot {user.id} ({user.username}) from {chat_id}")
            return
        except Exception as e:
            print(f"[YUTA AUTOREMOVE] Candidate failed for {user.id}: {e}")
            continue


    

