#                    REACT SYSTEM
# ═══════════════════════════════════════════════

react_chats: dict = {}

@only_owner
async def react_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _sessy_action_animation(update, "Reaction Control", "⚡")
    chat_id = update.effective_chat.id if update.effective_chat else None
    if chat_id is None:
        return
    if not context.args:
        current = react_chats.get(chat_id)
        return await _send_pfp_box(update, f"╭──〔 ⚡ 𝗥ᴇᴀᴄᴛ 〕──╮\n│ Status » {'🟢 ON' if current else '🔴 OFF'}\n│ Emoji  » {current or 'Not set'}\n│\n│ √react <emoji>\n│ √stopreact\n│\n│      ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")
    emoji = context.args[0].strip()
    if len(emoji) > 16:
        return await _send_pfp_box(update, "⚠️ 𝗘ᴍᴏᴊɪ 𝗡ᴏᴛ 𝗩ᴀʟɪᴅ.")
    react_chats[chat_id] = emoji
    await _send_pfp_box(update, f"╭──〔 ⚡ 𝗥ᴇᴀᴄᴛ 〕──╮\n│ 🟢 𝗦ᴛᴀᴛᴜs » ON\n│ ❤️ 𝗘ᴍᴏᴊɪ » {emoji}\n│\n│      ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")

@only_owner
async def stopreact_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _sessy_action_animation(update, "Reaction Stop", "🛑")
    chat_id = update.effective_chat.id if update.effective_chat else None
    if chat_id is not None:
        react_chats.pop(chat_id, None)
    await _send_pfp_box(update, "╭──〔 ⚡ 𝗥ᴇᴀᴄᴛ 〕──╮\n│ 🔴 𝗥ᴇᴀᴄᴛ 𝗢ғғ\n│\n│      ──〔  𝗬ᴜ𝗧ᴀ  〕───\n╰────────────────────╯")

async def react_message_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.effective_message
    chat = update.effective_chat
    if not msg or not chat or chat.id not in react_chats:
        return
    if getattr(msg.from_user, "is_bot", False):
        return
    emoji = react_chats.get(chat.id)
    if not emoji:
        return
    try:
        from telegram import ReactionTypeEmoji
        if hasattr(context.bot, "set_message_reaction"):
            await context.bot.set_message_reaction(chat_id=chat.id, message_id=msg.message_id, reaction=[ReactionTypeEmoji(emoji=emoji)], is_big=False)
    except Exception as e:
        logger.debug("Reaction failed: %s", e)


