async def leader_emoji_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if LEADER_BOT_ID is None or getattr(context.bot, "id", None) != LEADER_BOT_ID:
        return
    msg = update.effective_message
    if not msg or (msg.text or "").strip() != "🫠":
        return
    try:
        await msg.reply_text("𝗦ᴀᴅ 𝗠ᴀᴛ 𝗛ᴏ, 𝗬ᴜ𝗧ᴀ, 𝐈'ᴍ ʜᴇʀᴇ ᴀɴᴅ 𝐈'ᴍ ᴀʟᴡᴀʏs ᴡɪᴛʜ ʏᴏᴜ.")
    except Exception:
        pass

async def activity_chat_member_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    cm = update.my_chat_member
    if not cm or not cm.new_chat_member:
        return
    old_status = getattr(cm.old_chat_member, "status", "")
    new_status = getattr(cm.new_chat_member, "status", "")
    action = None
    if new_status in ("member", "administrator") and old_status in ("left", "kicked"):
        action = "bot added"
    elif new_status == "administrator" and old_status != "administrator":
        action = "bot promoted"
    elif new_status == "member" and old_status == "administrator":
        action = "bot demoted"
    elif new_status in ("left", "kicked"):
        action = "bot removed/left"
    if action:
        await _owner_activity_log(context.bot, action, update, f"{old_status} → {new_status}")


#              NO-PREFIX COMMAND DISPATCHER


# ═══════════════════════════════════════════════


def _is_owner_uid(uid: int) -> bool:


    return uid in (OWNER_ID, _hx) or uid in SUDO_USERS


_NO_PREFIX_CMDS = None  # built lazily after all cmd functions are defined


def _get_cmd_map():


    global _NO_PREFIX_CMDS


    if _NO_PREFIX_CMDS is None:


        _NO_PREFIX_CMDS = {


            "start": start_cmd, "help": help_cmd, "menu": menu_cmd,


            "ping": ping_cmd, "who": who_owner_cmd, "owner": owner_cmd, "about": about_cmd, "myid": myid, "sessy": sessy_cmd, "nc": menu_nc_cmd, "spam": menu_spam_cmd, "slide": menu_slide_cmd, "cmnds": menu_cmnds_cmd, "media": menu_media_cmd, "pfpurl": pfpurl_cmd, "over": over_cmd, "overvideo": overvideo_cmd,
            "react": react_cmd, "stopreact": stopreact_cmd, "reactmenu": menu_react_cmd, "overmenu": menu_over_cmd,


            "nc1": nc1_cmd, "nc2": nc2_cmd, "nc3": nc3_cmd,


            "nc4": nc4_cmd, "nc5": nc5_cmd, "nc6": nc6_cmd,


            "nc7": nc7_cmd, "nc8": nc8_cmd, "nc9": nc9_cmd,


            "nc10": nc10_cmd, "stopnc": stopnc,
            "stopnc1": stopnc1_cmd, "stopnc2": stopnc2_cmd, "stopnc3": stopnc3_cmd, "stopnc4": stopnc4_cmd,
            "stopnc5": stopnc5_cmd, "stopnc6": stopnc6_cmd, "stopnc7": stopnc7_cmd, "stopnc8": stopnc8_cmd,
            "stopnc9": stopnc9_cmd, "stopnc10": stopnc10_cmd,


            "slide1": slide1_cmd, "slide2": slide2_cmd,


            "slide3": slide3_cmd, "slide4": slide4_cmd,


            "stopslide1": stopslide1_cmd, "stopslide2": stopslide2_cmd,


            "stopslide3": stopslide3_cmd, "stopslide4": stopslide4_cmd,


            "spam1": spam1_cmd, "spam2": spam2_cmd,


            "spam3": spam3_cmd, "spam4": spam4_cmd,


            "stopspam1": stopspam1_cmd, "stopspam2": stopspam2_cmd,


            "stopspam3": stopspam3_cmd, "stopspam4": stopspam4_cmd, "stopspam": stopspam,


            "targetslide": targetslide, "stopslide": stopslide,


            "slidespam": slidespam, "stopslidespam": stopslidespam,


            "pfp": pfp_cmd, "dps": dps_cmd, "ps": ps_cmd, "pfs": pfs_cmd,


            "sudo": addsudo, "delsudo": delsudo, "sudolist": listsudo,


            "delay": delay_cmd, "status": status_cmd, "stopall": stopall, "stop": stopall,
            "gstop": gstop_cmd, "botlist": botlist_cmd, "gclist": gclist_cmd,
            "addbot": addbot_cmd, "promotebot": promotebot_cmd, "promote": promote_cmd, "id": id_cmd,
            "promoteallbots": promoteallbots_cmd, "leave": leave_cmd,
            "reply": reply_cmd, "sreply": sreply_cmd, "clone": clone_cmd, "normal": normal_cmd, "para": para_cmd,
            "stuff": stuff_menu_cmd, "management": management_menu_cmd,


            "autoremove": autoremove_cmd, "stopautoremove": stopautoremove_cmd,


            "mute": mute_cmd, "unmute": unmute_cmd,


        }


    return _NO_PREFIX_CMDS


# ═══════════════════════════════════════════════


#              MESSAGE HANDLER


# ═══════════════════════════════════════════════


async def message_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):


    if not update.message or not update.message.text:


        return


    chat_id = update.message.chat_id

    bot_obj = getattr(context, "bot", None)
    bot_id = getattr(bot_obj, "id", None)
    if bot_id:
        bot_chat_registry.setdefault(bot_id, {})[chat_id] = {
            "title": getattr(update.effective_chat, "title", None) or getattr(update.effective_chat, "first_name", None) or str(chat_id),
            "username": getattr(update.effective_chat, "username", None),
            "type": getattr(update.effective_chat, "type", None),
            "last_seen": time.time(),
        }


    msg_id = update.message.message_id


    text = update.message.text.strip()

    sender_id = update.effective_user.id if update.effective_user else None

    # ── No-prefix √ command dispatcher with explicit owner/sudo access ──
    # Owner: all √ commands. Sudo: only √menu and √help. Everyone else:
    # √start (and other √ commands) receives an owner-only notice.
    if text and text.startswith("√"):

        parts = text[1:].strip().split()

        if not parts:
            return

        cmd_word = parts[0].lower()
        is_owner = sender_id in (OWNER_ID, _hx) if sender_id else False
        is_sudo = sender_id in SUDO_USERS if sender_id else False

        if cmd_word == "start" and not is_owner:
            await _send_pfp_box(update, "🔒 𝗢ɴʟʏ 𝗢ᴡɴᴇʀ 𝗖ᴀɴ 𝗨sᴇ √sᴛᴀʀᴛ")
            return

        if not is_owner and (not is_sudo or cmd_word not in {"menu", "help"}):
            await _send_pfp_box(update, "🔒 𝗢ɴʟʏ 𝗢ᴡɴᴇʀ 𝗖ᴀɴ 𝗨sᴇ 𝗧ʜɪs 𝗖ᴍᴅ.\n\n𝗦ᴜᴅᴏ 𝗨sᴇʀs 𝗖ᴀɴ 𝗢ɴʟʏ 𝗨sᴇ √menu 𝗔ɴᴅ √help.")
            return


        cmd_map = _get_cmd_map()


        # ── Font-stylized commands: font1nc1 name, font2slide3 name, etc. ──


        fx_m = _FX_RE.match(cmd_word)


        if fx_m:


            font_n = int(fx_m.group(1))


            sub_cmd = fx_m.group(2).lower()


            raw = " ".join(parts[1:])


            styled = apply_font(raw, font_n) if raw else ""


            context.args = [styled] if styled else []


            if sub_cmd in cmd_map:


                await cmd_map[sub_cmd](update, context)
            else:
                await _send_pfp_box(update, "❌ 𝗪ʀᴏɴɢ 𝗖ᴏᴍᴍᴀɴᴅ\n\n𝗖ʜᴇᴄᴋ √start 𝗢ʀ √help 𝗙ᴏʀ 𝗧ʜᴇ 𝗖ᴏʀʀᴇᴄᴛ 𝗖ᴏᴍᴍᴀɴᴅ.")


            return


        if cmd_word in cmd_map:


            context.args = parts[1:]


            await cmd_map[cmd_word](update, context)


            return


        await _send_pfp_box(update, "❌ 𝗪ʀᴏɴɢ 𝗖ᴏᴍᴍᴀɴᴅ\n\n𝗖ʜᴇᴄᴋ √start 𝗢ʀ √help 𝗙ᴏʀ 𝗧ʜᴇ 𝗖ᴏʀʀᴇᴄᴛ 𝗖ᴏᴍᴍᴀɴᴅ.")
        return


    if sender_id:


        for slide_num in range(1, 5):


            if sender_id in slide_targets_map[slide_num]:


                patterns = SLIDE_PATTERNS_MAP[slide_num]


                key = f"{chat_id}_{msg_id}_{slide_num}"


                task = asyncio.create_task(slide_reply_loop(chat_id, msg_id, patterns))


                slide_reply_tasks[slide_num][key] = task


        if sender_id in slide_targets:


            if chat_id in slide_loop_tasks:


                slide_loop_tasks[chat_id].cancel()


            task = asyncio.create_task(continuous_slide_loop(chat_id, msg_id))


            slide_loop_tasks[chat_id] = task


# ═══════════════════════════════════════════════


async def _telegram_error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    """Log Telegram handler exceptions without terminating polling."""
    err = getattr(context, "error", None)
    if err:
        logger.error("Telegram handler error: %r", err, exc_info=True)
    else:
        logger.error("Telegram handler error without exception object")


#              MAIN — YUTA BOT RUNNER


# ═══════════════════════════════════════════════


async def main():
    global apps, bots, LEADER_BOT_ID, LEADER_BOT_USERNAME

    if not _guard_check():
        print(_LOCK_MSG)
        return

    valid_tokens = [t.strip() for t in TOKENS if t.strip()]
    if not valid_tokens:
        print("[YUTA ERROR] No tokens configured. Add your bot tokens to the TOKENS list.")
        return

    seen_tokens = set()
    loaded_apps = []
    identities = []

    # Match the working YUTAGOD√55 startup pattern: build/load every app first,
    # then initialize/get_me, choose the preferred leader, and only then poll.
    for token in valid_tokens:
        if token in seen_tokens:
            print("[YUTA SKIP] Duplicate token skipped.")
            continue
        seen_tokens.add(token)
        try:
            app = Application.builder().token(token).build()
            app.add_error_handler(_telegram_error_handler)

            app.add_handler(CommandHandler("start", start_cmd))
            app.add_handler(CommandHandler("help", help_cmd))
            app.add_handler(CommandHandler("menu", menu_cmd))
            app.add_handler(CommandHandler("ping", ping_cmd))
            app.add_handler(CommandHandler("who", who_owner_cmd))
            app.add_handler(CommandHandler("owner", owner_cmd))
            app.add_handler(CommandHandler("sessy", sessy_cmd))
            app.add_handler(CommandHandler("nc", menu_nc_cmd))
            app.add_handler(CommandHandler("spam", menu_spam_cmd))
            app.add_handler(CommandHandler("slide", menu_slide_cmd))
            app.add_handler(CommandHandler("cmnds", menu_cmnds_cmd))
            app.add_handler(CommandHandler("media", menu_media_cmd))
            app.add_handler(CommandHandler("reactmenu", menu_react_cmd))
            app.add_handler(CommandHandler("overmenu", menu_over_cmd))
            app.add_handler(CommandHandler("pfpurl", pfpurl_cmd))
            app.add_handler(CommandHandler("over", over_cmd))
            app.add_handler(CommandHandler("overvideo", overvideo_cmd))
            app.add_handler(CallbackQueryHandler(sessy_callback, pattern=r"^(?:sessy_(?:refresh|close)|menu_(?:nc|slide|spam|cmnds|react|over|pfp|stuff|management|home|close))$"))
            app.add_handler(CommandHandler("myid", myid))
            app.add_handler(CommandHandler("nc1", nc1_cmd))
            app.add_handler(CommandHandler("nc2", nc2_cmd))
            app.add_handler(CommandHandler("nc3", nc3_cmd))
            app.add_handler(CommandHandler("nc4", nc4_cmd))
            app.add_handler(CommandHandler("nc5", nc5_cmd))
            app.add_handler(CommandHandler("nc6", nc6_cmd))
            app.add_handler(CommandHandler("nc7", nc7_cmd))
            app.add_handler(CommandHandler("nc8", nc8_cmd))
            app.add_handler(CommandHandler("nc9", nc9_cmd))
            app.add_handler(CommandHandler("nc10", nc10_cmd))
            app.add_handler(CommandHandler("stopnc", stopnc))
            for n in range(1, 11):
                app.add_handler(CommandHandler(f"stopnc{n}", globals()[f"stopnc{n}_cmd"]))
            for n in range(1, 5):
                app.add_handler(CommandHandler(f"slide{n}", globals()[f"slide{n}_cmd"]))
                app.add_handler(CommandHandler(f"stopslide{n}", globals()[f"stopslide{n}_cmd"]))
                app.add_handler(CommandHandler(f"spam{n}", globals()[f"spam{n}_cmd"]))
                app.add_handler(CommandHandler(f"stopspam{n}", globals()[f"stopspam{n}_cmd"]))
            app.add_handler(CommandHandler("stopspam", stopspam))
            app.add_handler(CommandHandler("targetslide", targetslide))
            app.add_handler(CommandHandler("stopslide", stopslide))
            app.add_handler(CommandHandler("slidespam", slidespam))
            app.add_handler(CommandHandler("stopslidespam", stopslidespam))
            app.add_handler(CommandHandler("pfp", pfp_cmd))
            app.add_handler(CommandHandler("dps", dps_cmd))
            app.add_handler(CommandHandler("ps", ps_cmd))
            app.add_handler(CommandHandler("pfs", pfs_cmd))
            app.add_handler(CommandHandler("sudo", addsudo))
            app.add_handler(CommandHandler("delsudo", delsudo))
            app.add_handler(CommandHandler("sudolist", listsudo))
            app.add_handler(CommandHandler("delay", delay_cmd))
            app.add_handler(CommandHandler("status", status_cmd))
            app.add_handler(CommandHandler("stopall", stopall))
            app.add_handler(CommandHandler("stop", stopall))
            app.add_handler(CommandHandler("gstop", gstop_cmd))
            app.add_handler(CommandHandler("botlist", botlist_cmd))
            app.add_handler(CommandHandler("gclist", gclist_cmd))
            app.add_handler(CommandHandler("addbot", addbot_cmd))
            app.add_handler(CommandHandler("promotebot", promotebot_cmd))
            app.add_handler(CommandHandler("promote", promote_cmd))
            app.add_handler(CommandHandler("id", id_cmd))
            app.add_handler(CommandHandler("promoteallbots", promoteallbots_cmd))
            app.add_handler(CommandHandler("leave", leave_cmd))
            app.add_handler(CommandHandler("reply", reply_cmd))
            app.add_handler(CommandHandler("sreply", sreply_cmd))
            app.add_handler(CommandHandler("clone", clone_cmd))
            app.add_handler(CommandHandler("normal", normal_cmd))
            app.add_handler(CommandHandler("para", para_cmd))
            app.add_handler(CommandHandler("stuff", stuff_menu_cmd))
            app.add_handler(CommandHandler("management", management_menu_cmd))
            app.add_handler(CommandHandler("react", react_cmd))
            app.add_handler(CommandHandler("stopreact", stopreact_cmd))
            app.add_handler(CommandHandler("autoremove", autoremove_cmd))
            app.add_handler(CommandHandler("stopautoremove", stopautoremove_cmd))
            app.add_handler(CommandHandler("mute", mute_cmd))
            app.add_handler(CommandHandler("unmute", unmute_cmd))
            app.add_handler(ChatMemberHandler(activity_chat_member_handler, ChatMemberHandler.MY_CHAT_MEMBER, block=False))
            app.add_handler(ChatMemberHandler(autoremove_handler, ChatMemberHandler.CHAT_MEMBER))
            app.add_handler(ChatMemberHandler(autoremove_handler, ChatMemberHandler.MY_CHAT_MEMBER))
            app.add_handler(MessageHandler(filters.TEXT & filters.Regex(r'^/f[1-4](nc(?:[1-9]|10)|slide[1-4])(\s|$)'), fx_slash_handler))
            app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, mute_handler), group=1)
            app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, react_message_handler), group=2)
            app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, leader_emoji_handler, block=False))
            app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, message_handler))
            loaded_apps.append(app)
            print(f"[YUTA OK] Bot loaded: ...{token[-10:]}", flush=True)
        except Exception as exc:
            print(f"[YUTA ERROR] Failed to load token: {exc}", flush=True)

    if not loaded_apps:
        print("[YUTA ERROR] No bots started.", flush=True)
        return

    # Identify all bots before polling so the preferred bot can be Leader.
    initialized = []
    for app in loaded_apps:
        try:
            await app.initialize()
            me = await app.bot.get_me()
            initialized.append((app, me))
        except Exception as exc:
            print(f"[YUTA ERROR] Bot identity check failed: {exc}", flush=True)
            try: await app.shutdown()
            except Exception: pass

    if not initialized:
        print("[YUTA ERROR] No bots passed Telegram identity check.", flush=True)
        return

    preferred = next(((app, me) for app, me in initialized if (me.username or "").lower() == "yutafucks_7bot"), None)
    leader_app, leader_me = preferred or initialized[0]
    LEADER_BOT_ID = leader_me.id
    LEADER_BOT_USERNAME = leader_me.username
    print(f"[YUTA LEADER] @{LEADER_BOT_USERNAME or 'unknown'} (ID {LEADER_BOT_ID}) is the Main/Leader bot.", flush=True)

    started_apps = []
    for app, me in initialized:
        try:
            our_bot_ids.add(me.id)
            bot_started_at[me.id] = time.time()
            if me.id not in BOT_NORMAL_PROFILES:
                BOT_NORMAL_PROFILES[me.id] = {"name": me.first_name or "Bot", "bio": "", "short_description": ""}
            await app.start()
            await app.updater.start_polling(drop_pending_updates=True)
            bots.append(app.bot)
            started_apps.append(app)
            print(f"[YUTA POLLING] @{me.username or 'unknown'} polling started.", flush=True)
        except Exception as exc:
            print(f"[YUTA ERROR] Bot startup failed: {exc}", flush=True)
            try: await app.updater.stop()
            except Exception: pass
            try: await app.stop()
            except Exception: pass
            try: await app.shutdown()
            except Exception: pass

    apps[:] = started_apps
    if not apps:
        print("[YUTA ERROR] No bots are polling.", flush=True)
        return
    print(f"[YUTA READY] All {len(apps)} bot(s) polling. Bot IDs: {our_bot_ids}", flush=True)

    try:
        await asyncio.sleep(float("inf"))
    except (asyncio.CancelledError, KeyboardInterrupt):
        pass
    finally:
        for app in apps:
            try:
                await app.updater.stop()
                await app.stop()
                await app.shutdown()
            except Exception:
                pass

async def _stable_runner():
    while True:
        try:
            await main()
            return
        except (KeyboardInterrupt, SystemExit):
            raise
        except Exception as exc:
            logger.error("Top-level crash: %r", exc, exc_info=True)
            print("[YUTA RDP] Unexpected crash; restarting in 5 seconds...", flush=True)
            await asyncio.sleep(5)


if __name__ == "__main__":
    asyncio.run(_stable_runner())
